int integer(const std::string& text,int minimum,int maximum){size_t used=0;long long v=std::stoll(text,&used);if(used!=text.size()||v<minimum||v>maximum)throw std::runtime_error("Invalid desktop scene number");return static_cast<int>(v);}
double real(const std::string& text,double minimum,double maximum){size_t used=0;auto v=std::stod(text,&used);if(used!=text.size()||!std::isfinite(v)||v<minimum||v>maximum)throw std::runtime_error("Invalid weather coordinates");return v;}
std::wstring dos_path(std::wstring path){if(path.rfind(L"\\Device\\",0)==0){for(wchar_t letter=L'A';letter<=L'Z';++letter){wchar_t drive[]={letter,L':',0},native[32768]{};if(QueryDosDeviceW(drive,native,32768)){size_t n=wcslen(native);if(!_wcsnicmp(path.c_str(),native,n)&&(path.size()==n||path[n]==L'\\'))return std::wstring(drive)+path.substr(n);}}return L"\\\\?\\GLOBALROOT"+path;}if(path.rfind(L"\\??\\",0)==0){path.erase(0,4);if(path.rfind(L"UNC\\",0)==0)path=L"\\\\"+path.substr(4);}return path;}
unsigned long long birth(HANDLE h){FILETIME c{},e{},k{},u{};return GetProcessTimes(h,&c,&e,&k,&u)?(static_cast<unsigned long long>(c.dwHighDateTime)<<32)|c.dwLowDateTime:0;}
template<class T>struct Com{T* p=nullptr;~Com(){if(p)p->Release();}T* operator->()const{return p;}};
