void validate_desktop_scene(const DesktopScene& s){
    if(s.name.empty()||s.name.size()>120||s.notes.size()>4000||s.video.size()>32768||s.display.size()>256||s.location.size()>120||s.dock_style<0||s.dock_style>13||s.hover_animation<0||s.hover_animation>3||s.custom_accent>0xFFFFFF||s.custom_background>0xFFFFFF||s.custom_text>0xFFFFFF||s.accent<0||s.accent>4||s.opacity<0||s.opacity>255||s.icon_size<40||s.icon_size>72||s.dock_edge<0||s.dock_edge>3||s.wall_mode<1||s.wall_mode>4||(s.fps!=15&&s.fps!=24&&s.fps!=30)||s.edge_mode<0||s.edge_mode>2||s.edge_width<2||s.edge_width>12||s.columns<2||s.columns>4||s.widget_x<0||s.widget_x>1000||s.widget_y<0||s.widget_y>1000||s.widgets>63||s.pins.size()>24||s.zones.empty()||s.zones.size()>9||!std::isfinite(s.latitude)||!std::isfinite(s.longitude)||s.latitude< -90||s.latitude>90||s.longitude< -180||s.longitude>180)throw std::runtime_error("Desktop scene contains invalid values");
    if(s.music_x<0||s.music_x>1000||s.music_y<0||s.music_y>1000||s.music_width<160||s.music_width>960||s.music_height<50||s.music_height>320||s.skin<0||s.skin>9)throw std::runtime_error("Invalid visualizer bounds or skin");
    if(s.launcher_style<0||s.launcher_style>5||s.switcher_style<0||s.switcher_style>5||s.launcher_opacity<0||s.launcher_opacity>255||s.switcher_opacity<0||s.switcher_opacity>255||s.corner_size<8||s.corner_size>48||s.corner_dwell<200||s.corner_dwell>2000||s.hidden_apps.size()>48)throw std::runtime_error("Invalid desktop appearance or corner settings");for(int n=0;n<4;++n)if(s.corner_actions[n]<0||s.corner_actions[n]>8||s.corner_triggers[n]<0||s.corner_triggers[n]>2)throw std::runtime_error("Invalid corner action");for(auto& path:s.hidden_apps)if(path.empty()||path.size()>32768||!std::filesystem::path(wide(path)).is_absolute())throw std::runtime_error("Invalid hidden taskbar application");
    if(s.corners)for(int n=0;n<4;++n){if(s.corner_actions[n]==1&&!s.launcher)throw std::runtime_error("Enable App launcher for the chosen corner action");if(s.corner_actions[n]==2&&!s.switcher)throw std::runtime_error("Enable Window switcher for the chosen corner action");}
    if(s.board&&!s.widgets)throw std::runtime_error("Choose at least one widget or disable the widget board");
    for(const auto& p:s.pins)if(p.title.empty()||p.title.size()>200||p.path.empty()||p.path.size()>32768||!std::filesystem::path(wide(p.path)).is_absolute())throw std::runtime_error("Choose an absolute local path and a short name for each dock pin");
    for(const auto& z:s.zones)if(z.name.empty()||z.name.size()>80||z.x<0||z.y<0||z.w<50||z.h<50||z.x+z.w>1000||z.y+z.h>1000)throw std::runtime_error("Snap zones must stay inside the screen and be at least 5% wide/high");
    if(s.wallpaper&&s.wall_mode==4&&s.video.empty())throw std::runtime_error("Choose a local MP4 for the video wallpaper");
}
std::string encode_desktop_scene(const DesktopScene& s){validate_desktop_scene(s);Records r{{"desktop-scene","1",s.name,s.display,s.video,s.notes,std::to_string(s.accent),std::to_string(s.opacity),std::to_string(s.icon_size),std::to_string(s.dock_edge),std::to_string(s.wall_mode),std::to_string(s.fps),std::to_string(s.edge_mode),std::to_string(s.edge_width),std::to_string(s.columns),std::to_string(s.widget_x),std::to_string(s.widget_y),std::to_string(s.widgets),std::to_string(s.latitude),std::to_string(s.longitude),s.location}};std::string flags;for(bool value:{s.dock,s.board,s.wallpaper,s.launcher,s.switcher,s.edges,s.snap,s.interactive,s.start_menu})flags+=value?'1':'0';r.push_back({"features",flags});r.push_back({"shell",std::to_string(s.dock_style),std::to_string(s.hover_animation),std::to_string(s.custom_accent),std::to_string(s.custom_background),std::to_string(s.custom_text),s.custom_colors?"1":"0",s.replace_taskbar?"1":"0",s.replace_switcher?"1":"0",s.auto_hide?"1":"0"});r.push_back({"visual",std::to_string(s.music_x),std::to_string(s.music_y),std::to_string(s.music_width),std::to_string(s.music_height),std::to_string(s.skin)});r.push_back({"extras",std::to_string(s.launcher_style),std::to_string(s.switcher_style),std::to_string(s.launcher_opacity),std::to_string(s.switcher_opacity),s.music?"1":"0",s.corners?"1":"0",std::to_string(s.corner_size),std::to_string(s.corner_dwell)});for(int n=0;n<4;++n)r.push_back({"corner",std::to_string(n),std::to_string(s.corner_actions[n]),std::to_string(s.corner_triggers[n])});for(auto& path:s.hidden_apps)r.push_back({"hidden",path});for(auto& p:s.pins)r.push_back({"pin",p.title,p.path});for(auto& z:s.zones)r.push_back({"zone",z.name,std::to_string(z.x),std::to_string(z.y),std::to_string(z.w),std::to_string(z.h)});return encode(r);}
DesktopScene decode_desktop_scene(const std::string& record){auto rows=decode(record);if(rows.size()<3||rows.size()>96||rows[0].size()!=21||rows[0][0]!="desktop-scene"||rows[0][1]!="1"||rows[1].size()!=2||rows[1][0]!="features"||rows[1][1].size()!=9||rows[1][1].find_first_not_of("01")!=std::string::npos)throw std::runtime_error("Invalid desktop scene schema; original record preserved");DesktopScene s;auto& r=rows[0];s.name=r[2];s.display=r[3];s.video=r[4];s.notes=r[5];s.accent=integer(r[6],0,4);s.opacity=integer(r[7],0,255);s.icon_size=integer(r[8],40,72);s.dock_edge=integer(r[9],0,3);s.wall_mode=integer(r[10],1,4);s.fps=integer(r[11],15,30);s.edge_mode=integer(r[12],0,2);s.edge_width=integer(r[13],2,12);s.columns=integer(r[14],2,4);s.widget_x=integer(r[15],0,1000);s.widget_y=integer(r[16],0,1000);s.widgets=integer(r[17],0,63);s.latitude=real(r[18],-90,90);s.longitude=real(r[19],-180,180);s.location=r[20];auto f=rows[1][1];s.dock=f[0]=='1';s.board=f[1]=='1';s.wallpaper=f[2]=='1';s.launcher=f[3]=='1';s.switcher=f[4]=='1';s.edges=f[5]=='1';s.snap=f[6]=='1';s.interactive=f[7]=='1';s.start_menu=f[8]=='1';s.pins.clear();s.zones.clear();for(size_t i=2;i<rows.size();++i){const auto& row=rows[i];if(row.size()==6&&row[0]=="visual"){s.music_x=integer(row[1],0,1000);s.music_y=integer(row[2],0,1000);s.music_width=integer(row[3],160,960);s.music_height=integer(row[4],50,320);s.skin=integer(row[5],0,9);}else if(row.size()==9&&row[0]=="extras"){s.launcher_style=integer(row[1],0,5);s.switcher_style=integer(row[2],0,5);s.launcher_opacity=integer(row[3],0,255);s.switcher_opacity=integer(row[4],0,255);s.music=integer(row[5],0,1)!=0;s.corners=integer(row[6],0,1)!=0;s.corner_size=integer(row[7],8,48);s.corner_dwell=integer(row[8],200,2000);}else if(row.size()==4&&row[0]=="corner"){int n=integer(row[1],0,3);s.corner_actions[n]=integer(row[2],0,8);s.corner_triggers[n]=integer(row[3],0,2);}else if(row.size()==2&&row[0]=="hidden")s.hidden_apps.push_back(row[1]);else if(row.size()==10&&row[0]=="shell"){s.dock_style=integer(row[1],0,13);s.hover_animation=integer(row[2],0,3);s.custom_accent=integer(row[3],0,0xFFFFFF);s.custom_background=integer(row[4],0,0xFFFFFF);s.custom_text=integer(row[5],0,0xFFFFFF);s.custom_colors=integer(row[6],0,1)!=0;s.replace_taskbar=integer(row[7],0,1)!=0;s.replace_switcher=integer(row[8],0,1)!=0;s.auto_hide=integer(row[9],0,1)!=0;}else if(row.size()==3&&row[0]=="pin")s.pins.push_back({row[1],row[2]});else if(row.size()==6&&row[0]=="zone")s.zones.push_back({row[1],integer(row[2],0,1000),integer(row[3],0,1000),integer(row[4],50,1000),integer(row[5],50,1000)});else throw std::runtime_error("Unknown desktop scene record");}validate_desktop_scene(s);return s;}
DesktopScene desktop_preset(int preset){DesktopScene s;if(preset==0)return s;s.custom_colors=true;s.wallpaper=false;s.custom_text=RGB(240,242,248);if(preset==1){s.name="Focus desk";s.skin=2;s.accent=4;s.custom_accent=RGB(220,225,232);s.custom_background=RGB(23,24,28);s.widgets=9;s.icon_size=48;s.dock_style=9;s.auto_hide=true;s.opacity=248;s.hover_animation=1;s.launcher_style=s.switcher_style=1;}else if(preset==2){s.name="Creator desk";s.skin=9;s.accent=1;s.custom_accent=RGB(171,132,255);s.custom_background=RGB(19,17,32);s.dock_style=5;s.icon_size=56;s.widgets=19;s.music=true;s.music_width=480;s.music_height=100;s.music_y=700;s.launcher_style=s.switcher_style=3;s.hover_animation=2;s.opacity=238;}else if(preset==3){s.name="Compact desk";s.skin=4;s.accent=2;s.custom_accent=RGB(40,197,240);s.custom_background=RGB(12,23,35);s.board=false;s.dock_edge=2;s.dock_style=8;s.icon_size=40;s.auto_hide=true;s.hover_animation=0;s.opacity=250;s.launcher_style=s.switcher_style=2;}else throw std::runtime_error("Unknown desktop preset");validate_desktop_scene(s);return s;}
RECT desktop_zone(const SnapZone& z,const RECT& work){if(z.x<0||z.y<0||z.w<50||z.h<50||z.x+z.w>1000||z.y+z.h>1000||work.right<=work.left||work.bottom<=work.top)throw std::runtime_error("Invalid snap zone or display");auto w=work.right-work.left,h=work.bottom-work.top;return {work.left+MulDiv(w,z.x,1000),work.top+MulDiv(h,z.y,1000),work.left+MulDiv(w,z.x+z.w,1000),work.top+MulDiv(h,z.y+z.h,1000)};}
std::vector<std::pair<std::string,RECT>> desktop_displays(){std::vector<std::pair<std::string,RECT>> result;EnumDisplayMonitors(nullptr,nullptr,[](HMONITOR m,HDC,LPRECT,LPARAM data)->BOOL{MONITORINFOEXW info{};info.cbSize=sizeof info;if(GetMonitorInfoW(m,&info))reinterpret_cast<decltype(result)*>(data)->push_back({utf8(info.szDevice),info.rcWork});return TRUE;},reinterpret_cast<LPARAM>(&result));return result;}
std::vector<DesktopWindow> desktop_windows(HWND main_window){struct Context{std::vector<DesktopWindow> rows;DWORD session;HWND main;};Context context{{},0,main_window};ProcessIdToSessionId(GetCurrentProcessId(),&context.session);EnumWindows([](HWND w,LPARAM data)->BOOL{auto& c=*reinterpret_cast<Context*>(data);if(c.rows.size()>=48)return FALSE;if(!IsWindowVisible(w)||GetWindow(w,GW_OWNER)||(GetWindowLongPtrW(w,GWL_EXSTYLE)&WS_EX_TOOLWINDOW))return TRUE;DWORD pid=0,session=0;GetWindowThreadProcessId(w,&pid);if(!pid||!ProcessIdToSessionId(pid,&session)||session!=c.session||(pid==GetCurrentProcessId()&&w!=c.main))return TRUE;DWORD cloaked=0;if(SUCCEEDED(DwmGetWindowAttribute(w,DWMWA_CLOAKED,&cloaked,sizeof cloaked))&&cloaked)return TRUE;wchar_t title[512]{};GetWindowTextW(w,title,512);if(!*title)return TRUE;wchar_t cls[128]{};GetClassNameW(w,cls,128);if(std::wstring(cls)==L"Progman"||std::wstring(cls)==L"WorkerW"||std::wstring(cls)==L"Shell_TrayWnd")return TRUE;HANDLE process=OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION,FALSE,pid);if(!process)return TRUE;wchar_t path[32768]{};DWORD n=32768;auto created=birth(process);std::string file;if(QueryFullProcessImageNameW(process,0,path,&n))file=utf8(dos_path(path));CloseHandle(process);c.rows.push_back({w,pid,created,utf8(title),file,IsIconic(w)!=FALSE});return TRUE;},reinterpret_cast<LPARAM>(&context));return context.rows;}
std::string desktop_path_key(const std::string& path){std::wstring resolved=dos_path(wide(path));if(lower(utf8(std::filesystem::path(resolved).extension().wstring()))==".lnk"){HRESULT initialized=CoInitializeEx(nullptr,COINIT_APARTMENTTHREADED);{Com<IShellLinkW> link;Com<IPersistFile> file;if(SUCCEEDED(CoCreateInstance(CLSID_ShellLink,nullptr,CLSCTX_INPROC_SERVER,IID_IShellLinkW,reinterpret_cast<void**>(&link.p)))&&SUCCEEDED(link->QueryInterface(IID_IPersistFile,reinterpret_cast<void**>(&file.p)))&&SUCCEEDED(file->Load(resolved.c_str(),STGM_READ))){wchar_t target[32768]{};WIN32_FIND_DATAW data{};if(SUCCEEDED(link->GetPath(target,32768,&data,SLGP_RAWPATH))&&*target){wchar_t expanded[32768]{};auto n=ExpandEnvironmentStringsW(target,expanded,32768);if(n&&n<=32768)resolved=expanded;}}}if(SUCCEEDED(initialized))CoUninitialize();}HANDLE file=CreateFileW(resolved.c_str(),0,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,FILE_FLAG_BACKUP_SEMANTICS,nullptr);if(file!=INVALID_HANDLE_VALUE){BY_HANDLE_FILE_INFORMATION identity{};if(GetFileInformationByHandle(file,&identity)&&(identity.nFileIndexHigh||identity.nFileIndexLow)){CloseHandle(file);return "file:"+std::to_string(identity.dwVolumeSerialNumber)+":"+std::to_string(identity.nFileIndexHigh)+":"+std::to_string(identity.nFileIndexLow);}wchar_t final[32768]{};auto n=GetFinalPathNameByHandleW(file,final,32768,FILE_NAME_NORMALIZED|VOLUME_NAME_DOS);CloseHandle(file);if(n&&n<32768)resolved=final;}return lower(utf8(resolved));}
void desktop_launch(const std::string& requested){auto path=std::filesystem::path(wide(requested));if(!path.is_absolute()||!std::filesystem::exists(path))throw std::runtime_error("Pinned app/folder is missing; update this pin");if(!std::filesystem::is_directory(path)){auto ext=lower(utf8(path.extension().wstring()));if(ext!=".exe"&&ext!=".lnk")throw std::runtime_error("Only chosen applications, shortcuts and folders can be launched");}
    HRESULT initialized=CoInitializeEx(nullptr,COINIT_APARTMENTTHREADED);struct End{HRESULT r;~End(){if(SUCCEEDED(r))CoUninitialize();}} end{initialized};Com<IShellWindows> windows;Com<IDispatch> desktop,background,application;Com<IServiceProvider> provider;Com<IShellBrowser> browser;Com<IShellView> view;Com<IShellFolderViewDual> folder;Com<IShellDispatch2> shell;VARIANT empty{};long desktop_handle=0;
    if(FAILED(CoCreateInstance(CLSID_ShellWindows,nullptr,CLSCTX_LOCAL_SERVER,IID_IShellWindows,reinterpret_cast<void**>(&windows.p)))||FAILED(windows->FindWindowSW(&empty,&empty,SWC_DESKTOP,&desktop_handle,SWFO_NEEDDISPATCH,&desktop.p))||!desktop.p||FAILED(desktop->QueryInterface(IID_IServiceProvider,reinterpret_cast<void**>(&provider.p)))||FAILED(provider->QueryService(SID_STopLevelBrowser,IID_IShellBrowser,reinterpret_cast<void**>(&browser.p)))||FAILED(browser->QueryActiveShellView(&view.p))||FAILED(view->GetItemObject(SVGIO_BACKGROUND,IID_IDispatch,reinterpret_cast<void**>(&background.p)))||FAILED(background->QueryInterface(IID_IShellFolderViewDual,reinterpret_cast<void**>(&folder.p)))||FAILED(folder->get_Application(&application.p))||FAILED(application->QueryInterface(IID_IShellDispatch2,reinterpret_cast<void**>(&shell.p))))throw std::runtime_error("The desktop shell launch broker is unavailable; restart Explorer and retry");
    BSTR file=SysAllocString(path.c_str()),verb=SysAllocString(L"open");VARIANT operation{},show{};operation.vt=VT_BSTR;operation.bstrVal=verb;show.vt=VT_I4;show.lVal=SW_SHOWNORMAL;HRESULT result=shell->ShellExecute(file,empty,empty,operation,show);SysFreeString(file);SysFreeString(verb);if(FAILED(result))throw std::runtime_error("Desktop shell could not launch this item: "+error(static_cast<DWORD>(result)));
}
